import type {
  OutgoingMessage,
  ListSessionsMessage,
  SessionListMessage,
} from '../../types/messages.js';

async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore?: SessionStore,
  history?: {enabled: boolean}
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') return handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') {
    return handleListSessions(ws, session.userId, message, sessionStore, history);
  }
}

async function handleListSessions(
  ws: WebSocket,
  userId: string | number,
  message: ListSessionsMessage,
  sessionStore?: SessionStore,
  history?: {enabled: boolean}
): Promise<void> {
  if (!history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not enabled for this server');
    return;
  }

  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }

  const sessions = await sessionStore.listFor(userId, {
    limit: message.limit,
    before: message.before,
  });

  const frame: SessionListMessage = {
    type: 'session_list',
    sessions: sessions.map(s => ({
      sessionId: s.sessionId,
      createdAt: s.createdAt.toISOString(),
      updatedAt: s.updatedAt.toISOString(),
      entryCount: s.entryCount,
    })),
  };

  sendJson(ws, frame);
}

